from pathlib import Path
import numpy as np,json,math,hashlib
p=Path(__file__).resolve().parent;m=json.loads((p/'research/hdr-decode.json').read_text());w,h=m['width'],m['height'];a=np.fromfile(p/'research/hdr-decoded-rgba-f32.bin',dtype='<f4').reshape(h,w,4)[...,:3];lum=a@np.array([.2126,.7152,.0722]);y,x=np.unravel_index(lum.argmax(),lum.shape)
