mask=lum>=lum.max()*.25;ys,xs=np.nonzero(mask);weights=lum[mask];cu=float(np.average(xs+.5,weights=weights)/w);cv=float(np.average(ys+.5,weights=weights)/h)
r={'source':'sunset_in_the_chalk_quarry_1k.hdr','source_sha256':hashlib.sha256((p/'originals/sunset_in_the_chalk_quarry/sunset_in_the_chalk_quarry_1k.hdr').read_bytes()).hexdigest(),'dimensions':[w,h],'coordinate_convention':'Image pixels top-left; Three equirectUv atan(z,x)/(2*pi)+0.5, asin(y)/pi+0.5 with image upload flipY=true','peak_pixel':[int(x),int(y)],'peak_image_uv':[u,v],'peak_shader_uv':[u,1-v],'sun_toward_source_normalized':vec,'incoming_light_ray_normalized':[-z for z in vec],'azimuth_degrees_atan_z_x':math.degrees(lon),'elevation_degrees':math.degrees(lat),'environment_yaw_radians':0,'quarter_peak_cluster':{'count':int(mask.sum()),'weighted_image_uv':[cu,cv]},'linear_luminance':{'max':float(lum.max()),'unweighted_mean':float(lum.mean()),'sky_percentiles_50_95_99':np.percentile(lum[:h//2],[50,95,99]).tolist()},'starting_exposure':{'hdr_with_aces':1.0,'ldr_background':'Already tonemapped sRGB: sample to linear once and bypass second filmic tonemap or compensate separately. Keep exposure1 for the provider LDR.','status':'Integration starting values, not rendered acceptance.'},'rotation_contract':'If sampling u += yaw/(2*pi), sun world azimuth becomes native azimuth minus yaw. Rotate direct-light direction by the same inverse lookup yaw. For a rotated sphere instead, rotate the sun vector by the sphere world rotation.'}
